import { Block, type BlockProps } from "@prototyp/skeletor";
import type { FC, PropsWithChildren } from "react";
import { isIpad } from "shared/utils";

export const IpadScreenWrapper: FC<PropsWithChildren<BlockProps>> = ({
  children,
  ...props
}) => {
  if (!isIpad()) return children;

  return (
    <Block
      flex={1}
      maxWidth={800}
      margins={{ marginHorizontal: "auto" }}
      {...props}
    >
      {children}
    </Block>
  );
};

content.text:
You can check `Object.keys(props).length > 0` inside the component — `props` already holds everything except `children`:

```tsx
export const IpadScreenWrapper: FC<PropsWithChildren<BlockProps>> = ({
  children,
  ...props
}) => {
  const hasExtraProps = Object.keys(props).length > 0;
  // ...
};
```

Since `...props` spreads all `BlockProps` except `children`, any prop passed by the caller will appear there. `hasExtraProps` is `true` when at least one non-`children` prop was provided.
